import{z as o,x as d,o as r,c as B,q as E,j as i,D as t,d as A,s as n,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"撞库与速率限制","description":"","frontmatter":{"title":"撞库与速率限制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/credential-stuffing.md","filePath":"cs/credential-stuffing.md","lastUpdated":1791413859000}'),p={name:"cs/credential-stuffing.md"};function f(c,a,h,u,m,S){const s=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=E('<h1 id="撞库与速率限制" tabindex="-1">撞库与速率限制 <a class="header-anchor" href="#撞库与速率限制" aria-label="Permalink to &quot;撞库与速率限制&quot;">​</a></h1><div class="epigraph"><p>别处泄漏的口令会被拿到你这再试。速率限制、多因素、泄漏口令检测降低自动化成功率；复杂密码规则挡不住已泄漏的那条。</p><footer>—— 据 OWASP Credential Stuffing；NIST SP 800-63B；对照[密码破解](/cs/password-cracking)</footer></div><p>上一课<a href="/cs/business-logic-flaws">业务逻辑</a>是工作流。缺口是<strong>认证入口被自动化</strong>。离线破解是哈希；本课是在线。不给撞库操作指导。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户复用口令：泄漏语料里同一口令跨站点复现率很高，攻击者持的不是猜测而是正确答案的副本。离线要对付哈希与盐（回<a href="/cs/password-cracking">密码破解</a>），在线撞库只要极低的单次成功率即有收益；源地址用住宅代理与僵尸网络分摊，纯按 IP 限流天然失效。缺口：速率限制要按账户与地址分层、锁定策略防 DoS、MFA、已知泄漏口令检查。</p><p><span class="marginnote">术语翻译：撞库就是「拿着别处泄漏的账号密码清单来你这再试一遍」——因为用户爱在多个网站复用同一个密码，攻击者不需要猜，只需要在正确的清单里碰。</span></p><h3 id="验证码不是根" tabindex="-1">验证码不是根 <a class="header-anchor" href="#验证码不是根" aria-label="Permalink to &quot;验证码不是根&quot;">​</a></h3><p>可被农场绕过——人工打码按条计价，把验证码折成单价问题。它只抬高单位成本，作辅助信号，不当边界。登录速度、设备指纹、口令命中泄漏语料的比例才是可用信号。</p><p><span class="marginnote">OWASP。禁止撞库教程。WAF 下一课是另一层过滤。泄漏口令检查可走 k-匿名式查询：客户端只发 SHA-1 前 5 位 hex，对照 <a href="/cs/k-anonymity">k-匿名</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层：按账户、按 IP、按 ASN 三档阈值，账户档用滚动失败计数，命中后升难度（退避、CAPTCHA、二次验证）而非硬锁——硬锁是攻击者手里的 DoS 工具。注册与改密时拒收已知泄漏口令。MFA 用 <a href="/cs/totp-mfa">TOTP</a> 或 <a href="/cs/webauthn-fido2">WebAuthn</a> 抗重放，SMS 弱于 SIM 交换；无口令直接删掉可重放的共享秘密。NIST 800-63B 把节流定成义务，量级示例是按账户日百次失败。下一课 WAF。</p>',12)),(r(),i(l,null,{default:t(()=>[n(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEAK%5B%22%E5%A4%96%E9%83%A8%E6%B3%84%E6%BC%8F%E5%AF%B9%22%5D%20--%3E%20TRY%5B%22%E5%9C%A8%E4%BD%A0%E8%BF%99%E7%99%BB%E5%BD%95%22%5D%0A%20%20TRY%20--%3E%20RL%5B%22%E9%80%9F%E7%8E%87%E9%99%90%E5%88%B6%22%5D%0A%20%20TRY%20--%3E%20MFA%5B%22%E7%AC%AC%E4%BA%8C%E5%9B%A0%E7%B4%A0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：100 万条泄漏对、单次成功率仅 0.2%，就是约 2000 个账户中招；把每次尝试的成本（验证码、退避、封号风险）抬高十倍，期望收益就被打穿——限流的经济逻辑就在这笔账上。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"在线模型受接口约束，故限流有效：每次尝试暴露在网络上，可被计数、延迟、拒绝；离线破解没有这个反馈通道，这是两课的分界。限流的经济性：撞库单价低、总量大，把单次成本抬高一个数量级就打穿期望收益。失败模式：阈值过紧锁出共享出口（校园、CGNAT）的正常用户；信号库有隐私与误报成本；对已泄漏的高价值账户，限流挡不住针对性人工登录，仍要 MFA。WAF 下一课挡一部分自动化与注入噪声。",-1)),(r(),i(l,null,{default:t(()=>[n(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E4%B8%80%E6%AC%A1%E7%99%BB%E5%BD%95%E5%B0%9D%E8%AF%95%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20C1%5B%22%E8%B4%A6%E6%88%B7%E6%A1%A3%3A%20%E6%BB%9A%E5%8A%A8%E5%A4%B1%E8%B4%A5%E8%AE%A1%E6%95%B0%22%5D%0A%20%20REQ%20--%3E%20C2%5B%22IP%20%E6%A1%A3%E8%AE%A1%E6%95%B0%22%5D%0A%20%20REQ%20--%3E%20C3%5B%22ASN%20%E6%A1%A3%E8%AE%A1%E6%95%B0%22%5D%0A%20%20C1%20--%3E%20HIT%7B%22%E5%93%AA%E4%B8%80%E6%A1%A3%E8%B6%85%E9%98%88%E5%80%BC%3F%22%7D%0A%20%20HIT%20--%3E%7C%22%E6%98%AF%22%7C%20STEP%5B%22%E5%8D%87%E9%9A%BE%E5%BA%A6%3A%20%E9%80%80%E9%81%BF%2F%E9%AA%8C%E8%AF%81%E7%A0%81%2F%E4%BA%8C%E6%AC%A1%E9%AA%8C%E8%AF%81%22%5D%0A%20%20HIT%20--%3E%7C%22%E5%90%A6%22%7C%20NORM%5B%22%E6%AD%A3%E5%B8%B8%E5%A4%84%E7%90%86%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p><span class="marginnote">常见误区：初学者容易以为「封 IP」就够了——住宅代理让每次尝试换个地址；也别以为「错几次就锁死账号」很安全：攻击者可以故意输错，把你千千万万个用户锁在门外，硬锁反过来成了他的 DoS 工具，所以正确姿势是升难度而不是硬锁。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写工具用法。阈值按业务流量定，不是常数。WAF 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逻辑洞之后，认证口仍会被泄漏口令打。</li><li>限流、MFA、禁已知泄漏。</li><li>在线不等于离线哈希破解。</li><li>下一课 WAF。</li><li>出处：OWASP Credential Stuffing；NIST SP 800-63B。</li></ul>',5))])}const D=o(p,[["render",f]]);export{T as __pageData,D as default};
